function _winhttpGet(host, path) {
    const WINHTTP_FLAG_SECURE = 0x00800000;
    const WINHTTP_ACCESS_TYPE_DEFAULT_PROXY = 0;
    try { Module.load("winhttp.dll"); } catch (_) {}
    const wh = (name, ret, args) => new NativeFunction(Module.findExportByName("winhttp.dll", name), ret, args);
    const WinHttpOpen = wh("WinHttpOpen", "pointer", ["pointer", "uint32", "pointer", "pointer", "uint32"]);
    const WinHttpConnect = wh("WinHttpConnect", "pointer", ["pointer", "pointer", "uint32", "uint32"]);
    const WinHttpOpenRequest = wh("WinHttpOpenRequest", "pointer", ["pointer", "pointer", "pointer", "pointer", "pointer", "pointer", "uint32"]);
    const WinHttpSendRequest = wh("WinHttpSendRequest", "int", ["pointer", "pointer", "uint32", "pointer", "uint32", "uint32", "pointer"]);
    const WinHttpReceiveResponse = wh("WinHttpReceiveResponse", "int", ["pointer", "pointer"]);
    const WinHttpQueryDataAvailable = wh("WinHttpQueryDataAvailable", "int", ["pointer", "pointer"]);
    const WinHttpReadData = wh("WinHttpReadData", "int", ["pointer", "pointer", "uint32", "pointer"]);
    const WinHttpCloseHandle = wh("WinHttpCloseHandle", "int", ["pointer"]);

    let hSession = NULL, hConnect = NULL, hRequest = NULL;
    try {
        hSession = WinHttpOpen(Memory.allocUtf16String("Ryker"), WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, NULL, NULL, 0);
        if (hSession.isNull()) throw new Error("WinHttpOpen failed");
        hConnect = WinHttpConnect(hSession, Memory.allocUtf16String(host), 443, 0);
        if (hConnect.isNull()) throw new Error("WinHttpConnect failed");
        hRequest = WinHttpOpenRequest(hConnect, Memory.allocUtf16String("GET"), Memory.allocUtf16String(path), NULL, NULL, NULL, WINHTTP_FLAG_SECURE);
        if (hRequest.isNull()) throw new Error("WinHttpOpenRequest failed");
        if (!WinHttpSendRequest(hRequest, NULL, 0, NULL, 0, 0, NULL)) throw new Error("WinHttpSendRequest failed");
        if (!WinHttpReceiveResponse(hRequest, NULL)) throw new Error("WinHttpReceiveResponse failed");

        let out = "";
        const avail = Memory.alloc(4);
        const read = Memory.alloc(4);
        while (true) {
            if (!WinHttpQueryDataAvailable(hRequest, avail)) break;
            const sz = avail.readU32();
            if (sz === 0) break;
            const buf = Memory.alloc(sz + 1);
            if (!WinHttpReadData(hRequest, buf, sz, read)) break;
            const n = read.readU32();
            if (n === 0) break;
            out += buf.readUtf8String(n);
        }
        return out;
    } finally {
        try { if (!hRequest.isNull()) WinHttpCloseHandle(hRequest); } catch (_) {}
        try { if (!hConnect.isNull()) WinHttpCloseHandle(hConnect); } catch (_) {}
        try { if (!hSession.isNull()) WinHttpCloseHandle(hSession); } catch (_) {}
    }
}

