function getGrenadeLauncherComponent(gameObject) {
    if (!gameObject || gameObject.isNull?.()) return null;
    try {
        const comp = gameObject.method('GetComponent', 0).inflate(GrenadeLauncherClass).invoke();
        if (comp && !comp.isNull()) return comp;
    } catch (_) {}
    try {
        const comp = gameObject.method('GetComponentInChildren', 2).overload('System.Type', 'System.Boolean').invoke(GrenadeLauncherClass.type.object, true);
        if (comp && !comp.isNull()) return comp;
    } catch (_) {}
    return null;
}

function getAllLaunchableItemIDs() {
    const ids = [];
    const seen = new Set();
    for (const id of itemIDs) {
        const cleanId = String(id || '').trim();
        if (!cleanId || cleanId === 'item_grenade_launcher' || seen.has(cleanId)) continue;
        seen.add(cleanId);
        ids.push(cleanId);
    }
    return ids;
}

function buildLauncherAmmoArray(mode) {
    const ammo = [];
    const allItems = mode === 'random' ? getAllLaunchableItemIDs() : [];
    const unreleasedItems = ['item_motor', 'item_sludge', 'item_piston', 'item_deck_of_chances', 'item_brick', 'item_tv_remote'];
    
    for (let i = 0; i < 200; i++) {
        if (mode === 'rainbow_snowball') {
            ammo.push({ itemID: 'item_snowball', hue: clampSignedByte(Math.random() * 255 - 127), saturation: clampSignedByte(Math.random() * 148 - 20), scale: clampSignedByte(Math.random() * 256 - 128) });
        } else if (mode === 'random') {
            const id = allItems[i % allItems.length];
            ammo.push({ itemID: id, hue: clampSignedByte(Math.random() * 255 - 127), saturation: clampSignedByte(Math.random() * 148 - 20), scale: clampSignedByte(Math.random() * 256 - 128) });
        } else if (mode === 'suitcase') {
            ammo.push({ itemID: 'item_pelican_case', hue: clampSignedByte(Math.random() * 255 - 127), saturation: clampSignedByte(Math.random() * 148 - 20), scale: clampSignedByte(Math.random() * 256 - 128) });
        } else if (mode === 'crate') {
            ammo.push({ itemID: 'item_crate', hue: 0, saturation: 0, scale: 0 });
        } else if (mode === 'unreleased') {
            const id = unreleasedItems[i % unreleasedItems.length];
            ammo.push({ itemID: id, hue: 0, saturation: 0, scale: 0 });
        }
    }
    return ammo;
}

function spawnFilledGrenadeLauncher(pos, mode) {
    try {
        const launcherObj = spawnItemAtPos('item_grenade_launcher', pos, identityQuaternion);
        if (!launcherObj || launcherObj.isNull?.()) {
            spawnItemAsync('item_grenade_launcher', pos, identityQuaternion);
            return;
        }
        
        const go = launcherObj.method('get_gameObject').invoke();
        const launcherComp = getGrenadeLauncherComponent(go);
        
        if (launcherComp && !launcherComp.isNull()) {
            activeLaunchers.push({ object: launcherObj, mode: mode });
        }
    } catch (e) {
        console.error('[Grenade Launcher] Spawn Error:', e);
    }
}

function activateLauncherGun(mode) {
    currentLauncherMode = mode;
    launcherTriggerWasDown = !!leftTrigger;
    launcherNextFireTime = 0;
    sendNotification(getLauncherDisplayName(mode) + ' activated', false);
}

function deactivateLauncherGun(mode) {
    currentLauncherMode = null;
    launcherTriggerWasDown = false;
    sendNotification(getLauncherDisplayName(mode) + ' deactivated', false);
}

function updateLauncherGunState(mode) {
    if (currentLauncherMode !== mode) return;
    if (!rightGrab) {
        launcherTriggerWasDown = false;
        return;
    }
    
    const gunData = omniRenderGun();
    if (!gunData || !gunData.endPosition) return;
    
    if (!rightTrigger) {
        launcherTriggerWasDown = false;
        return;
    }
    
    if (launcherTriggerWasDown) return; 
    launcherTriggerWasDown = true;
    
    if (time < launcherNextFireTime) return;
    launcherNextFireTime = time + (rapidFireLauncherEnabled ? 0.1 : 0.35);
    
    spawnFilledGrenadeLauncher(gunData.endPosition, mode);
}

function getLauncherDisplayName(mode) {
    const names = {
        'suitcase': 'Suitcase Grenade Launcher',
        'crate': 'Crate Grenade Launcher',
        'rainbow_snowball': 'Rainbow Snowball Launcher',
        'unreleased': 'Unreleased Item Launcher',
        'random': 'Random Item Grenade Launcher'
    };
    return names[mode] || 'Grenade Launcher';
}

function getMultiLaunchAmount() {
    return multiLaunchAmounts[multiLaunchAmountIndex] || 2;
}

function cycleMultiLaunchAmount() {
    multiLaunchAmountIndex = (multiLaunchAmountIndex + 1) % multiLaunchAmounts.length;
    sendNotification('Multi Launch Amount: ' + getMultiLaunchAmount(), false);
}

