    function renderGridCells(canvasObject, mods, pulsedOutline) {
        const root = getTransform(menu);
        const COLS = 2, ROWS = 5;
        const COL_Y = [0.081, -0.081];
        const ROW_Z = [0.046, 0.009, -0.028, -0.065, -0.102];
        const CELL_W = 0.145, CELL_H = 0.027;
        const cellSY = CELL_W / 0.3, cellSZ = CELL_H / 0.3825;
        const boxSY = 0.016 / 0.3, boxSZ = 0.017 / 0.3825;
        const miniSY = 0.015 / 0.3;
        const P = pulsedOutline;
        const cellFill = [bgColor[0] * 0.55, bgColor[1] * 0.55, bgColor[2] * 0.55, 0.90];
        const cellFillOn = [P[0] * 0.16, P[1] * 0.16, P[2] * 0.16, 0.95];
        const borderDim = [P[0] * 0.34, P[1] * 0.34, P[2] * 0.34, 1];
        const boxOff = [bgColor[0] * 0.3, bgColor[1] * 0.3, bgColor[2] * 0.3, 0.95];

        createOutlinedRoundedObject([0.104, 0, 0.080], [0.09, 0.92, 0.006],
            borderDim, [0, 0, 0, 0], root, false, 0.0);
        createOutlinedRoundedObject([0.105, 0, 0.080], [0.089, 0.40, 0.007],
            P, [0, 0, 0, 0], root, false, 0.0);
        for (const ey of [0.138, -0.138]) {
            createOutlinedRoundedObject([0.105, ey, 0.080], [0.089, 0.020, 0.020],
                P, [0, 0, 0, 0], root, false, 0.0);
        }

        for (let i = 0; i < mods.length && i < COLS * ROWS; i++) {
            const bd = mods[i];
            const col = i % COLS, row = Math.floor(i / COLS);
            const cy = COL_Y[col], cz = ROW_Z[row];
            const leftEdge = cy + CELL_W / 2, rightEdge = cy - CELL_W / 2;

            const lit = !!(bd.isTogglable && bd.enabled);
            createOutlinedRoundedObject([0.104, cy, cz], [0.088, cellSY, cellSZ],
                lit ? cellFillOn : cellFill, lit ? P : borderDim, root, false, 0.0016);

            if (bd.stepDown && bd.stepUp) {
                for (const st of [[bd.stepDown, leftEdge - 0.012, "-"], [bd.stepUp, rightEdge + 0.012, "+"]]) {
                    try {
                        const mb = createOutlinedRoundedObject([0.106, st[1], cz], [0.086, miniSY, boxSZ],
                            boxOff, pulsedOutline, root, true, 0.0016);
                        mb.method("set_name").invoke(Il2Cpp.string("@" + st[0].activationId));
                        addComponent(mb, GorillaReportButton);
                        renderMenuText(canvasObject, st[2], textColor, [0.11, st[1], cz], [0.014, 0.018]);
                    } catch (_) { }
                }
                let lbl = bd.buttonText;
                if (_pcMode && _pcMenuOpen && i === _pcMenuSelector) lbl = "> " + lbl;
                renderMenuText(canvasObject, lbl, textColor, [0.11, cy, cz], [0.080, 0.020]);
                continue;
            }

            try {
                const hit = createOutlinedRoundedObject([0.105, cy, cz], [0.087, cellSY, cellSZ],
                    [0, 0, 0, 0], [0, 0, 0, 0], root, true, 0.0);
                hit.method("set_name").invoke(Il2Cpp.string("@" + bd.activationId));
                addComponent(hit, GorillaReportButton);
            } catch (_) { }

            const on = lit;
            createOutlinedRoundedObject([0.1055, leftEdge - 0.0035, cz],
                [0.087, 0.0040 / 0.3, (CELL_H * 0.60) / 0.3825],
                on ? P : borderDim, [0, 0, 0, 0], root, false, 0.0);
            const bx = leftEdge - 0.018;
            createOutlinedRoundedObject([0.107, bx, cz], [0.085, boxSY, boxSZ],
                boxOff, on ? P : borderDim, root, false, 0.0014);
            if (on) {
                createOutlinedRoundedObject([0.108, bx, cz], [0.084, boxSY * 0.48, boxSZ * 0.48],
                    P, [0, 0, 0, 0], root, false, 0.0);
            }

            let lbl = bd.buttonText;
            if (_pcMode && _pcMenuOpen && i === _pcMenuSelector) lbl = "> " + lbl;
            renderMenuText(canvasObject, lbl, textColor, [0.11, cy - 0.015, cz], [0.104, 0.020]);
        }
    }

