    function shutdownRunner() {
        let disconnected = false;
        try {
            const prefabGenInstance = PrefabGen.field("_instance").value;
            if (prefabGenInstance && !prefabGenInstance.isNull()) {
                const runner = prefabGenInstance.method("get_runner").invoke();
                if (runner && !runner.isNull()) {
                    try { runner.method("Shutdown").invoke(); disconnected = true; } catch (_) {}
                }
            }
        } catch (_) {}
        try {
            const networkrunner = SFXManager.method("get__currentRunner").invoke();
            if (networkrunner && !networkrunner.isNull?.()) {
                try { networkrunner.method("Shutdown").invoke(); disconnected = true; } catch (_) {}
            }
        } catch (_) {}
        try {
            const manager = NManager.method("get_instance").invoke();
            if (manager && !manager.isNull?.()) {
                try { manager.method("TryShutdownAndCancelConnecting").invoke(); } catch (_) { }
                if (!disconnected) {
                    try { manager.method("Shutdown").invoke(); } catch (_) {}
                }
            }
        } catch (_) {}
    }
