    function dumpItemIds() {
        try {
            const runner = PrefabGen.field("_instance").value.method("get_runner").invoke();
            if (!runner || runner.isNull()) { sendNotification("No runner found", true); return; }
            const sources = runner.field("_config").value.field("PrefabTable").value.field("_sources").value;
            const count = sources.method("get_Count").invoke();
            const found = [];
            for (let i = 0; i < count; i++) {
                try {
                    const source = sources.method("get_Item").invoke(i);
                    let desc = "";
                    try { desc = source.method("get_Description").invoke().content || ""; } catch (_) {}
                    if (desc.indexOf("item_") === -1) continue;
                    const bare = desc.replace(/^.*[\\\/]/, "").replace(/\.prefab$/i, "").replace(/^item_prefab\//, "");
                    if (bare.indexOf("item_") !== 0) continue;
                    if (found.indexOf(bare) !== -1) continue;
                    found.push(bare);
                } catch (_) {}
            }
            if (found.length === 0) { sendNotification("No items found in prefab table", true); return; }
            const env = Il2Cpp.corlib.class("System.Environment");
            const userProfile = env.method("GetFolderPath").invoke(40);
            const path = userProfile.content + "\\Downloads\\item_ids.json";
            Il2Cpp.corlib.class("System.IO.File").method("WriteAllText", 2).invoke(
                Il2Cpp.string(path), Il2Cpp.string(JSON.stringify(found.sort(), null, 2))
            );
            sendNotification("Dumped " + found.length + " items to Downloads", false);
        } catch (e) {
            try { sendNotification("Dump failed: " + e, true); } catch (_) {}
        }
    }
    buttons[9] = [templateBackButton()];
    buttons[11] = [templateBackButton()];
    function findExistingButton(label) {
        for (const page of buttons) {
            const found = page.find((button) => button.buttonText === label);
            if (found)
                return found;
        }
        const pending = allSettingsButtons.find((button) => button.buttonText === label);
        return pending || null;
    }
    function settingsRange(startLabel, endLabel) {
        const start = allSettingsButtons.findIndex((button) => button.buttonText === startLabel);
        const end = endLabel
            ? allSettingsButtons.findIndex((button) => button.buttonText === endLabel)
            : allSettingsButtons.length;
        if (start < 0)
            return [];
        return allSettingsButtons.slice(start, end >= 0 ? end : allSettingsButtons.length);
    }
