    function loadAppScene(index, additive) {
        try {
            const smImage = images["UnityEngine.SceneManagementModule"] || (() => { images["UnityEngine.SceneManagementModule"] = syteSafeImage("UnityEngine.SceneManagementModule"); return images["UnityEngine.SceneManagementModule"]; })();
            if (!smImage) { sendNotification("SceneManagement image missing", true); return; }
            const sceneManager = smImage.class("UnityEngine.SceneManagement.SceneManager");
            sceneManager.method("LoadScene", 2).invoke(index, additive ? 1 : 0);
            sendNotification("loading AppScene " + index, false);
        }
        catch (e) { try { sendNotification("scene load failed: " + e, true); } catch (_) { } }
    }
