    function dumpHeldItemApi() {
        try {
            const held = getLocalHeldItem(true);
            if (!held || held.isNull?.()) { sendNotification("hold an item first", true); return; }
            const seen = new Set();
            const dumpClass = (obj, label) => {
                try {
                    let klass = obj.class;
                    let depth = 0;
                    while (klass && depth++ < 4) {
                        const cname = String(klass.name || "");
                        if (seen.has(cname)) break;
                        seen.add(cname);
                        console.log("=== " + label + " :: " + cname + " ===");
                        try {
                            for (const f of (klass.fields || [])) {
                                if (f.isStatic) continue;
                                console.log("  field " + String(f.type?.name || "?") + " " + String(f.name));
                            }
                        }
                        catch (_) { }
                        try {
                            for (const m of (klass.methods || [])) {
                                const ps = (m.parameters || []).map((p) => String(p.type?.name || "?")).join(", ");
                                console.log("  method " + String(m.name) + "(" + ps + ")");
                            }
                        }
                        catch (_) { }
                        try { klass = klass.parent; } catch (_) { break; }
                    }
                }
                catch (_) { }
            };
            dumpClass(held, "held");
            try {
                const go = held.method("get_gameObject").invoke();
                const CompCls = coreImage.class("UnityEngine.Component");
                const comps = go.method("GetComponentsInChildren", 1).inflate(CompCls).invoke(true);
                const n = Number(comps?.length || 0);
                for (let i = 0; i < n; i++) {
                    try { dumpClass(comps.get(i), "component[" + i + "]"); } catch (_) { }
                }
            }
            catch (_) { }
            sendNotification("dumped held item API -> console", false);
        }
        catch (e) {
            try { sendNotification("dump failed: " + e, true); } catch (_) { }
        }
    }
