    function vfxZeroArg(type) {
        if (type.class.isEnum || type.isPrimitive) return 0;
        if (!type.class.isValueType) return NULL;
        const fs = type.class.fields.filter(f => !f.isStatic);
        return fs.length ? fs.map(f => vfxZeroArg(f.type)) : 0;
    }
    let _vfxPlayMethod = null;
    function vfxGetPlayMethod() {
        if (_vfxPlayMethod) return _vfxPlayMethod;
        const pm = acImage.class("AnimalCompany.ParticleManager");
        let chosen = null;
        try {
            for (const m of pm.method("Play").overloads()) {
                if (m.parameterCount === 5) { chosen = m; break; }
            }
        } catch (_) {}
        if (!chosen) chosen = pm.method("Play");
        _vfxPlayMethod = chosen;
        return chosen;
    }
    function vfxSpawn(id, pos, rot) {
        try {
            const m = vfxGetPlayMethod();
            const colorArg = vfxZeroArg(m.parameters[3].type);
            m.invoke(id, pos, rot, colorArg, 8.0);
            return true;
        } catch (e) { sendNotification("vfx error: " + e, true); return false; }
    }

