    /* ================== MOM BOSS ================== */
    function mbGet() {
        try {
            const cls = acImage.class("AnimalCompany.MomBossController");
            let inst = null;
            try { inst = cls.field("_instance").value; } catch (_) { }
            if (!inst || (inst.isNull && inst.isNull())) {
                try {
                    const UO = Il2Cpp.domain.assembly("UnityEngine.CoreModule").image.class("UnityEngine.Object");
                    inst = UO.method("FindObjectOfType", 0).inflate(cls).invoke();
                } catch (_) { }
            }
            if (inst && (!inst.handle || !inst.handle.isNull())) return inst;
        } catch (_) { }
        return null;
    }
    function mbCall(name, ...args) {
        try {
            const inst = mbGet();
            if (!inst) { sendNotification("Mom Boss not found", true); return false; }
            inst.method(name).invoke(...args);
            sendNotification("MomBoss: " + name, false);
            return true;
        } catch (e) { console.log("[MomBoss] " + name + " failed: " + e); return false; }
    }
    function mbCallEither(a, b, ...args) { return mbCall(a, ...args) || mbCall(b, ...args); }
    function mbSpawnAtHand() {
        const ids = ["MomBossController", "mom_pillow", "item_momboss_box", "MomToyBlockObject"];
        try {
            const p = rightHandTransform.method("get_position").invoke();
            for (const id of ids) {
                try {
                    let obj = spawnItemAtPos(id, p, identityRotation);
                    if (obj && !obj.isNull?.()) { sendNotification("mom spawn: " + id, false); return true; }
                } catch (_) { }
                try { spawnItemAsync(id, p, identityRotation); sendNotification("mom spawn async: " + id, false); return true; } catch (_) { }
            }
        } catch (_) { }
        sendNotification("mom spawn failed", true);
        return false;
    }
    function mbTeleportMe() {
        try {
            const inst = mbGet();
            if (!inst) { sendNotification("Mom Boss not found", true); return; }
            const mp = inst.method("get_transform").invoke().method("get_position").invoke();
            const lp = NetPlayer.method("get_localPlayer").invoke();
            if (!lp || lp.isNull?.()) { sendNotification("local player null", true); return; }
            mmR.teleport(lp, [mp.field("x").value, mp.field("y").value + 2, mp.field("z").value]);
            sendNotification("tp'd to mom boss", false);
        } catch (e) { sendNotification("tp failed: " + e, true); }
    }
    function mbKill() {
        try {
            const inst = mbGet();
            if (!inst) { sendNotification("Mom Boss not found", true); return; }
            let hit = false;
            for (const m of ["TakeDamage", "ApplyDamage", "Damage", "Hit", "InstantKill", "Kill"]) {
                try { inst.method(m).invoke(9999); hit = true; break; } catch (_) { }
                try { inst.method(m).invoke(9999, [0, 0, 0]); hit = true; break; } catch (_) { }
                try { inst.method(m).invoke(); hit = true; break; } catch (_) { }
            }
            if (!hit) {
                if (!mbCall("SetDeathGameState") && !mbCall("SetFatalHitGameState")) {
                    sendNotification("mom kill: no method worked", true); return;
                }
            }
            sendNotification("mom boss killed", false);
        } catch (e) { sendNotification("mom kill failed: " + e, true); }
    }
    function mbSupplyBurst() {
        try {
            const inst = mbGet();
            let n = 0;
            if (inst) {
                let sp = null; try { sp = inst.method("get_itemSpawner").invoke(); } catch (_) { }
                if (sp && !sp.isNull?.()) {
                    try { sp.method("SpawnSupplyItems").invoke(); n++; } catch (_) { }
                }
            }
            if (n === 0) {
                const p = rightHandTransform.method("get_position").invoke();
                const pos = [p.field("x").value, p.field("y").value, p.field("z").value];
                for (const id of ["item_arena_pistol", "item_shotgun_ammo", "item_company_ration_heal", "item_rpg_ammo"]) {
                    for (let i = 0; i < 4; i++) {
                        try {
                            const sp = Vector3.method(".ctor", 3).invoke(
                                pos[0] + (Math.random() - 0.5) * 1.5,
                                pos[1] + Math.random(),
                                pos[2] + (Math.random() - 0.5) * 1.5);
                            spawnItemAsync(id, sp, identityRotation); n++;
                        } catch (_) { }
                    }
                }
            }
            sendNotification("supply burst x" + n, false);
        } catch (e) { sendNotification("supply burst failed: " + e, true); }
    }
